snippet_css:
:root{
  --bg: #0B0B0C;
  --fg: #F5EFE1;
  --muted: #C9B77A;
  --surface: rgba(255,255,255,.08);
  --border: rgba(212,175,55,.34);
  --accent: #D4AF37;
  --accent-fg: #0B0B0C;
  --accent-grad: linear-gradient(180deg,#E9D9A6,#D4AF37);
  --radius: 2px;
  --radius-sm: 2px;
  --shadow: 0 14px 34px rgba(0,0,0,.6);
  --btn-shadow: 0 0 0 1px rgba(212,175,55,.6);
  --art-bg: radial-gradient(circle at 50% 100%,#000 30%,transparent 70%),linear-gradient(160deg,#12213F,#0F5B4D 55%,#0B0B0C);
  --media-bg: linear-gradient(160deg,#12213F,#0F5B4D);
  --cta-bg: linear-gradient(180deg,rgba(15,91,77,.55),rgba(18,33,63,.55));
  --input-bg: rgba(255,255,255,.08);
  --ok: #1F7A63;
  --warn: #B4302B;
  --font-display: 'Limelight','Poiret One','Noto Serif TC',serif;
  --font-body: 'Josefin Sans','Noto Sans TC',sans-serif;
  --font-mono: 'Josefin Sans',ui-monospace,'SFMono-Regular',monospace;
  --focus-ring: var(--accent);
}

